import numpy as np


def relu(x):
    return np.maximum(0, x)


def conv_output_size(n, kernel, stride=1, padding=0):
    return (n + 2 * padding - kernel) // stride + 1


def max_pool_2x2(x):
    rows, cols = x.shape
    return x.reshape(rows // 2, 2, cols // 2, 2).max(axis=(1, 3))


def residual_block(x, W1, W2):
    return relu(x + relu(x @ W1) @ W2)


print("LeNet: 32x32 input, 5x5 conv ->", conv_output_size(32, 5))
print("VGG: 224x224 input, 3x3 conv, padding 1 ->", conv_output_size(224, 3, stride=1, padding=1))
print("ResNet stem: 224x224 input, 7x7 conv, stride 2, padding 3 ->", conv_output_size(224, 7, stride=2, padding=3))

feature_map = np.array([[1, 3, 2, 0],
                        [4, 2, 1, 5],
                        [0, 1, 7, 2],
                        [3, 2, 4, 6]])
print("2x2 max pool:")
print(max_pool_2x2(feature_map))

x = np.array([[1.0, -2.0, 3.0]])
print("residual block with zero weights:", residual_block(x, np.zeros((3, 3)), np.zeros((3, 3))))
